<?php
declare(strict_types=1);require __DIR__.'/app.php';header('Content-Type: application/json; charset=utf-8');
if(!current_user()||$_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals(csrf_token(),(string)($_POST['csrf']??''))){http_response_code(403);echo json_encode(['answer'=>'Inicia sesión de nuevo para continuar.']);exit;}
$q=mb_strtolower(trim((string)($_POST['question']??'')),'UTF-8');$ans='Puedo orientar sobre membresías, pagos, horarios y servicios. Prueba: “planes”, “precio”, “mi membresía”, “pagos” o “asistencia”.';
if(preg_match('/plan|membres|precio|costo|cu[aá]nto/iu',$q)){$plans=db()->query('SELECT name,description,price,duration_days FROM plans WHERE active=1 ORDER BY duration_days')->fetchAll();if($plans){$ans="Estos son los planes disponibles:\n";foreach($plans as $p)$ans.='• '.$p['name'].' — '.money($p['price']).' por '.$p['duration_days'].' días'.($p['description']?' ('.$p['description'].')':'')."\n";}else $ans='En este momento no hay planes publicados. Consulta en recepción.';}
elseif(preg_match('/horario|hora|abren|cierran|abierto|ubicaci[oó]n|direcci[oó]n|d[oó]nde/iu',$q)){$ans='La sede es Gimnasio Mutatio, en El Alto, Bolivia. Horarios y ubicación exacta: consulta en recepción, ya que aún no están configurados en el sistema.';}
elseif(preg_match('/mi membres|mi plan|vigencia|vence|vencimiento/iu',$q)){$c=client_for_user();$m=$c?active_membership((int)$c['id']):null;$ans=$m?'Tu plan '.$m['plan_name'].' está vigente hasta '.date('d/m/Y',strtotime($m['end_date'])).'.':'Tu cuenta no tiene una membresía activa vinculada. Consulta con recepción.';}
elseif(preg_match('/pago|historial|transacci[oó]n|debo|adeudo/iu',$q)){$c=client_for_user();if(!$c&&is_admin())$ans='Para consultar un historial individual, usa el módulo Pagos y busca por nombre del cliente.';elseif(!$c)$ans='Tu cuenta aún no está vinculada a un perfil de cliente.';else{$s=db()->prepare('SELECT payment_date,amount,method,reference FROM payments WHERE client_id=? ORDER BY payment_date DESC LIMIT 5');$s->execute([$c['id']]);$r=$s->fetchAll();$ans=$r?"Tus pagos recientes:\n":'No hay pagos asociados a tu perfil.';foreach($r as $p)$ans.='• '.date('d/m/Y',strtotime($p['payment_date'])).' — '.money($p['amount']).' ('.$p['method'].')'.($p['reference']?' · '.$p['reference']:'')."\n";}}
elseif(preg_match('/asistencia|visita|frecuencia/iu',$q)){$c=client_for_user();if($c){$s=db()->prepare('SELECT COUNT(*) FROM attendance WHERE client_id=? AND checkin_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)');$s->execute([$c['id']]);$ans='Registras '.$s->fetchColumn().' visitas en los últimos 30 días. ¡Mantén el ritmo!';}else $ans='El módulo Asistencia permite revisar registros y frecuencia de visitas.';}
elseif(preg_match('/gracias|hola|buenos/iu',$q))$ans='¡Hola! Soy el asistente local de Mutatio. Estoy aquí para ayudarte con planes, pagos y asistencia.';
echo json_encode(['answer'=>$ans],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
